declare(strict_types=1);
require_once __DIR__.'/_bootstrap.php';$filters=incident_filters($_GET);$result=$errorIncidentService->search($filters,1,5000);$name='incidentes-sietelsa-'.date('Ymd-His').'.csv';$safeCsv=static function(mixed $value): string{$value=(string)$value;return preg_match('/^[=+\-@\t\r]/',$value)?"'".$value:$value;};header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$name.'"');header('X-Content-Type-Options: nosniff');header('Cache-Control: no-store, private');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,['incidente','fecha','usuario','rol','ip','url','metodo','modulo','accion','codigo','excepcion','mensaje','estado','observacion']);foreach($result['items'] as $i)fputcsv($out,array_map($safeCsv,[$i['incidente_uuid'],$i['creado_en'],$i['usuario_nombre'],$i['rol'],$i['ip'],$i['url'],$i['metodo_http'],$i['modulo'],$i['accion'],$i['codigo_http'],$i['excepcion'],$i['mensaje_tecnico'],$i['estado'],$i['observacion_administrativa']]));fclose($out);exit;
